    'cli.headless.permission_hint' => '  ヒント: 名前付きモードなしの `-p` 実行は質問する `default` モードで開始します。無人実行では応答者がいないためフェイルクローズします。スクリプト実行では --permission-mode bypass-permissions（または accept-edits）を指定して続行できます。',
    'cli.help.screen' => <<<'TXT'
CandyCode — ターミナル向けAIコーディングアシスタント。

使い方:
  candy-code                       対話型TUIを開始（デフォルト）
  candy-code <dir>                 <dir> をルートとしてTUIを開始（<dir> は
                                   存在必須。最初の引数のみで有効）
  candy-code [<dir>] <words…>      TUIを開始し、wordsを最初の
                                   プロンプトとして送信（例: candy-code fix the bug）
  candy-code -c                    直近のセッションを続行
  candy-code --resume [<id>]       保存済みセッションを再開（id省略でピッカー表示）
  candy-code -p <prompt>           単一プロンプトを実行して終了（ワンショット）
  candy-code run "<prompt>"        -p "<prompt>" のエイリアス（ワンショットモード）
  candy-code --output-format json  機械可読JSONを出力（ワンショット）
  candy-code --worktree [<name>]   このセッションを専用のgit worktreeで
                                   実行（存在しなければ作成）

サブコマンド（いずれもTUIを開かず、プロバイダー、APIキー、
ターミナルを必要としません。serveとmcp serveは停止まで
動作し続けます — attachは両方の例外: 稼働中サーバーの
セッションでTUIを実行; acpはエディタが切断するまでターンを実行）:
  bundles list           このディレクトリが見るプラグインバンドルを一覧表示: 名前、
                         バージョン、ティア、各バンドルが持つサーフェス —
                         candy-codeが実行を拒否するフックと.mcp.json
                         を含む。
  bundles install <src>  バンドルディレクトリをコピー、またはgit URLを
                         深さ1のクローンで取得し、ユーザーバンドルルート
                         （~/.candy-code/bundles）に配置（所有権はあなたのみ）。
  doctor                 このインストールを検査し、すべての問題を報告:
                         PHPバージョン、セッションストアとserveが
                         必要とする拡張機能、設定ファイル、権限
                         ポリシー、選択されたプロバイダー、セッションデータベース、
                         プロジェクトMCP設定。いずれかのチェックが
                         失敗した場合終了コード1。
                         モデルから呼び出せる"doctor"ツールとは別物。
                         後者はターミナルの画像プロトコルをモデルに報告します。
  import claude          Claude Code設定のインポートをプレビュー: Claudeのユーザー
                         設定ファイル、および--project指定時の起動ルート下の.claude
                         設定ファイルを読み取り、permissionsのallow/deny/askリストを
                         permissionRulesに変換（厳しい側が優先—denyがallowに勝つ）、
                         モデルをマッピングし、対応先のないキーをすべてskippedとして
                         記録。確認前に何も書き込まれない: --yesで印刷済みプレビューを
                         即座に承認、未指定時は対話型ターミナルに確認を要求。
                         プレビューは確認なしの実行範囲を広げるallowルールを
                         すべて列挙する。
  login <provider>       プロバイダを1つログイン: claude-codeとcodexは
                         自前のCLIにターミナルを委譲（トークンはcandy-codeを
                         経由しない）; openai、anthropic、geminiは
                         設定ファイルのprovidersブロックにキーを貼り付け;
                         残りは実際に認証情報を所有する者を示す。
  models                 このインストールが選択可能なプロバイダと、
                         各プロバイダのデフォルトモデルを一覧表示; "*"は
                         選択中を示す。
  session list [--all|--archived|--children] [--limit N]
                         保存済みセッションを一覧表示。ピン留め→新着順:
                         id、最終更新、種別、ターン数、provider/model
                         および名称（★はピン留め行）。--childrenで
                         サブエージェント・バックグラウンド行を追加、
                         --archivedでアーカイブ済み、--allで両方追加;
                         --limit未指定時は20行。
  session show <target>  1セッションの詳細とトランスクリプトを表示。
  session rename <target> <title…>
                         セッションのリネーム; target以降の語が
                         タイトルになる。
  session delete <target> [--with-children]
                         セッションを削除。サブエージェントの子は
                         一緒に削除; ブランチは--with-childrenまで保持。
  session pin|unpin|archive|unarchive <target>
                         セッションをピン留め（一覧先頭、削除対象外）、
                         またはアーカイブ（デフォルト一覧から非表示、保持）。
                         <target>はid、名称、または一意なid接頭辞。
                         一致なしでexit 1、接頭辞が曖昧でexit 2
                         （候補を一覧表示）。
  mcp list               .mcp.jsonが宣言するMCPサーバーを一覧表示。
                         起動はしない。ファイル不在、プロジェクトツリー
                         外への解決、または存在するがプロジェクトルートが
                         未信頼の場合はその旨を報告。
  mcp trust              このプロジェクトの.mcp.jsonを現状のまま承認:
                         ルートを"trustedProjectMcp"に追加し、各サーバーの
                         command、args、envを記録。以降の変更は再承認まで
                         起動時に拒否される。
                         何も起動しない。
  mcp import claude|opencode|claude-project <path> [--write user]
                         外部MCP設定を変換し、等価な.mcp.jsonブロックを
                         stdoutに出力。デフォルトは表示のみ;
                         --write userで変換済みエントリを
                         ユーザーの~/.candy-code/mcp.jsonに追記
                         （名称衝突時は書き込み全体を拒否、プロジェクト
                         層は書き込まれない）。変換時のリネームは
                         stderrに列挙。
  mcp serve [--root PATH]
                         candy-code自体をstdio経由のMCPサーバーとして提供:
                         1行1フレームのJSON-RPC入力、1行1応答の出力、
                         stdin閉鎖まで継続。ツール呼び出しは読み取り専用
                         ロスター（Read, Glob, Grep, Ls, RepoMap）を実行、
                         ワークスペースルートに閉じ込め、起動時のPermissionGate
                         とPreToolUseフックチェーンを経由—これはクライアントが
                         起動できるMCPサーバー; WebSocketの
                         `candy-code serve`は依然MCPを話さない。停止まで
                         実行継続。
  lsp install <language> 1言語のピン留め済み言語サーバーをインストール:
                         npmパッケージまたはチェックサム検証済みリリース
                         バイナリを、ホーム下のプライベートインストール
                         ルートに配置。`lsp list`でインストール可能な
                         言語を確認。
  lsp list               インストール可能な全言語を報告: ピン留め
                         バージョン、サーバーのインストール先（未インストール
                         も含む）、このマシンのOS・アーキテクチャ向け
                         リリースの有無。何も起動せず、
                         何もダウンロードしない。
  self-update [--check] [--rollback] [--allow-unsigned] [--channel=stable|dev]
                         このpharインストールを最新公開のcandy-code
                         リリースに置換、スワップ前にリリースサイドカーで
                         sha256検証; 実行中のpharは<phar>.oldとして保持、
                         --rollbackでそのコピーを1回だけ復元。リリース
                         ソースに署名公開鍵がピン留めされている場合、
                         candy-code.phar.minisig署名も検証必須
                         （--allow-unsignedはその検証のみスキップ）。
                         --checkは現在と最新の比較報告のみ、更新ありで
                         exit 1。Composerインストールは明示的に拒否し、
                         代わりに実行すべきcomposer updateコマンドを
                         提示。devビルドはデフォルトでローリングの
                         candy-code/devリリースを追跡（リリースのtarget
                         commitがstampのshaと一致すれば最新）、--channelで
                         明示的にいずれかのトレインを選択。
                         train を明示的に選択します。
  serve [--host <ip>] [--port <n>] [--allow-remote] [--allowed-host <list>]
        [--allowed-ips <list>] [--allowed-origin <list>] [--allow-dir-browse]
        [--browse-root <dir>] [--web-root <dir>] [--no-web] [--allow-bypass]
        [--allow-root] [--detach] [--parent-pid <pid>]
        [--tls-cert <file>] [--tls-key <file>]
                         Web UI が接続する WebSocket + HTTP サーバーを、
                         Ctrl+C までフォアグラウンドで実行。デフォルトで 127.0.0.1:7420
                         にバインドし、ワンタイムコードをブラウザ Cookie に
                         交換するサインイン URL を表示。すべてのクライアントに
                         必要（~/.candy-code/server/token のトークンでも可）。
                         ループバック含む。オプション:
      --host <ip>        バインド先アドレス（デフォルト 127.0.0.1; localhost と ::1
                         もループバックとして扱う）。他のアドレスは --allow-remote
                         なしでは拒否。
      --port <n>         バインド先ポート（デフォルト 7420; 0 で空きポートを自動選択）。
      --allow-remote     非ループバックの --host を許可。--tls-cert と
                         --tls-key なしでは平文 HTTP: TLS リバースプロキシを
                         前面に配置するか、TLS を直接提供（下記参照）。
                         0.0.0.0 や :: では、このマシンの全アドレスで応答し、
                         サインイン URL にそれらが記載される。
      --tls-cert <file>  リスナーが TLS を提供する PEM 証明書。
                         --tls-key と併用。サインイン URL は https:// となり、
                         セッション Cookie に Secure が付き、
                         平文 http:// クライアントには一切応答しない。
      --tls-key <file>   --tls-cert 用の PEM 秘密鍵: 読み取り可能で、
                         グループ・その他ビットが公開されていない、証明書と
                         一致するファイル。不正・不完全なペアは起動時に拒否。
      --allowed-host <list>
                         サーバーが応答する追加のホスト名（または host:port）を
                         カンマ区切りで指定。例: このマシンの DNS 名。
                         複数回指定可。
      --allowed-ips <list>
                         接続を許可するクライアント IP または CIDR 範囲を
                         カンマ区切りで指定（例: 1.2.3.4,10.0.0.0/8）。他の
                         アドレスはサインイン前に 403 で拒否。ループバックは
                         常に許可。未設定: アドレスフィルタなし。
                         複数回指定可。
      --allowed-origin <list>
                         サーバー自身の他に許可するブラウザの Origin を
                         カンマ区切りで指定（http(s)://host[:port]）。
                         複数回指定可。
      --allow-dir-browse サインイン済みクライアントが新規セッションの開始
                         ディレクトリを選択可能に。--browse-root 配下の
                         ディレクトリ名のみ一覧表示（ファイルは不可）。デフォルト無効。
      --browse-root <dir>
                         --allow-dir-browse が限定されるディレクトリ
                         （デフォルト: ホームディレクトリ）。
      --web-root <dir>   インストール済みの sugarcraft/candy-code-web パッケージ
                         ではなく、<dir> から Web UI を提供。
      --no-web           API と WebSocket のみ提供。UI ファイルはなし。
      --allow-bypass     bypass-permissions または dont-ask モードでの
                         セッション実行を許可（デフォルト拒否; サーバーのセッションは
                         --permission-mode で変更しない限り default で開始）。
      --allow-root       root での実行を許可（デフォルト拒否）。
      --detach           バックグラウンド実行: ポートバインド後に URL と pid を
                         表示して終了。サーバーログは状態ディレクトリの
                         server.log に出力。
      --parent-pid <pid> プロセス <pid> 終了時にサーバーを停止（エディタや TUI が
                         専用サーバーを起動する場合用）。
                         ext-pcntl、ext-posix、ext-ffi がなければ起動拒否
                         （doctor 参照）。ポートが使用中、または同一状態ディレクトリで
                         既にサーバーが稼働中の場合は終了コード 1 で終了。
  serve status           稼働中サーバーの情報を表示: pid、URL、root、稼働時間、
                         GET /api/health の応答有無。サーバー未稼働時は
                         終了コード 1 で終了。
  serve stop [--force]   サーバー停止: SIGTERM 送信、最大 30 s でドレイン、未停止なら SIGKILL。
      --force            即座に SIGKILL。
  serve logs [-f]        デタッチ済みサーバーのログ末尾を表示。
  -f, --follow           追記分を継続表示（停止まで）。
  serve url [--qr]       新しいワンタイムコード付きサインイン URL を表示。
      --qr              サインイン URL をターミナル QR コードとして表示。
  serve token [--rotate] クライアントが送信するオーナートークン（Bearer）を表示。
      --rotate           トークンを更新。稼働中サーバーは再起動まで旧トークンを
                         使用継続。
  attach [<session>] [--url <url>]
                         実行中の candy-code のセッションで TUI を実行
                         serve: サーバーが毎ターン実行され、そのツールも、
                         このターミナルがそれらを表示し、権限リクエストに応答します
                         提起する質問。<session> は ID、名前、または
                         サーバーのセッションのいずれかの一意なIDプレフィックス;
                         指定しない場合は新規作成されます。サーバーは
                         one serve status のレポート、トークンは～から取得
                         CANDY_CODE_SERVER_TOKEN または状態ディレクトリの
                         トークンファイル。終了するとデタッチされ、実行中のターンは
                         on。サーバーが応答しない場合、終了コード 1 で終了。
      --url <url>        <url> のサーバーに接続 (アドレス serve
                         代わりに出力) します。
  acp                    Agent Client Protocol エージェントとして実行: エディター
                         (Zed, JetBrains, Neovim) が起動して通信する
                         stdin と stdout 経由の JSON-RPC。セッションは次で開かれます 
                         エディタのプロジェクトルートで、この
                         インストールのプロバイダとツールで実行し、エディタが
                         権限確認に回答する。ターミナルでは不可: stdout
                         はプロトコルのみを出力（その他はすべて
                         stderr）。エディタが stdin を閉じると exit 0。
  completion bash|zsh|fish
                         シェル補完スクリプトを stdout に出力。例:
                         eval "$(candy-code completion bash)".
  usage [7|30|all] [--session <target>]
                         永続的な支出台帳を日別・モデル別に集計:
                         `/usage` が表示するのと同じページ、同じ共有
                         集計で。7 と 30 は UTC の丸日（当日含む）、
                         all（または引数なし）は台帳全体を範囲とし、
                         その範囲外のウィンドウは暗黙に拡張せず
                         拒否する。--session は 1 つのセッションに
                         id、名前または一意のプレフィックスで絞り込み; --output-format json
                         はページ構築元のファクトマップを出力。読み取り
                         不能な台帳は理由を表示して exit 1;
                         価格未設定のモデルを含む集計の金額は
                         ≥ 下限値として表示し、単純合計では表示しない。

オプション:
  -p, --prompt <text>    コマンドラインでプロンプトを指定（ワンショットモード）
      --output-format <format>
                         出力形式: "text"（デフォルト）、"json" または
                         "stream-json"（NDJSON イベント、回答は最後）
      --root <dir>       カレントディレクトリの代わりに <dir> を
                         プロジェクトルートとして使用。--root=<dir> 形式も可
                         （<dir> が "-" で始まる場合に使用）; 省略不可。
                         ここでルート指定し、かつ位置引数でも
                         ルートを指定した場合は暗黙に優先せず拒否。
      --config <file>    設定、権限、信頼済みフックルートを
                         ~/.candy-code/config.json の代わりに <file> から読み込み。
                         --config=<file> 形式も可。既に存在し、
                         読み取り可能で、自分の所有であり、ファイルも
                         そのディレクトリも world-writable であってはならない —
                         権限ポリシーを含むため、~/.candy-code/config.json と
                         同じ基準で検証される（/etc や
                         /tmp 下のファイルは通常これらの理由で拒否）。
                         移動するのは FILE のみ: agents、skills、workflows、
                         sessions、memory は ~/.candy-code に残る。
      --model <name>     会話モデルとして <name> を使用し、
                         $CANDY_CODE_MODEL とプロバイダのデフォルトを上書き。
                         --model=<name> 形式も可。モデルを選択するもので、プロバイダは
                         選択しない — プロバイダは $CANDY_CODE_PROVIDER または
                         永続化された `provider` 設定から決定され、両者は
                         独立した軸。
      --permission-mode <mode>
                         設定ファイルのモードの代わりに <mode> で実行。
                         --permission-mode=<mode> 形式も可。最優先:
                         $CANDY_CODE_PERMISSION_MODE と
                         permissionMode 設定キーを上書き。いずれか 1 つ:
                         default、accept-edits、plan、auto、dont-ask、
                         bypass-permissions。未設定時、TUI と -p は
                         default で開始（書き込みとシェル
                         コマンド前に確認）; ローカル起動のデーモン
                         のみ bypass-permissions で開始。
      --max-cost <usd>   この起動を報告された支出 <usd> 米ドルで
                         上限設定: 上限を超えるターンは
                         送信せず拒否。--max-cost=<usd> 形式も可。
                         最優先: $CANDY_CODE_MAX_COST と
                         maxCostUsd 設定キーを上書き。小数可、
                         先頭の $ 許容（$2.50）; 0 と負数は
                         「上限なし」と解釈せず拒否。/budget は
                         実行中セッションの上限を上げたり解除できる。
      --max-turns <n>    この起動をツールループステップ <n> で
                         上限設定: すべて使い切ったターンは
                         その場で停止し理由を表示。--max-turns=<n> 形式も可。
                         最優先: maxToolSteps 設定キーを上書き（この軸
                         に対応する環境変数はない）。正の整数;
                         0 は「上限なし」と解釈せず拒否し、
                         使用不能な値は設定に暗黙に委譲せず
                         起動を拒否する。
      --json-schema <path-or-json>
                         回答を JSON Schema に制約: インラインの
                         {"type":"object",...} ドキュメントまたはそれを含む
                         ファイルへのパス。--json-schema=<value> 形式も可;
                         パスが "-" で始まる場合は = 形式を使用。
                         スキーマ制約回答に対応すると報告する
                         プロバイダのみリクエストを実行
                         — それ以外は exit 2 で拒否し、
                         制約なし回答に課金しない。スキーマは
                         ターンの自己完了リクエストを制約; ツールループを
                         継続するステップは自由（強制 JSON 回答は
                         ツール呼び出しを運べない）。
      --append-system-prompt <text-or-@file>
                         この起動のシステムプロンプトに
                         運用者ルールを追加: インラインテキスト、または
                         ルールを含むファイルへの @path。--append-system-prompt=<value> 形式も可;
                         パスが "-" で始まる場合は = 形式を使用
                         "-"で区切られる。ルールは追加のフェンス付き
                         個人指示ブロックとして届くが、上書きではない：
                         上位レイヤーを置換・降格することはできず、
                         テキスト内の偽造ブロックマーカーは無効化される。
                         指示ドキュメントと同じサイズ上限。
                         -p または run 動詞でのみ有効：追加先プロンプトが
                         ない起動は exit 2 で拒否し、与えたルールを
                         黙って無視することはない。
  -c, --continue         新規セッション開始ではなく、最後に使用したセッションを
                         履歴込みで再開する。このフラグなしでは
                         毎回新しいセッションが開くが、空の入力欄で
                         Up を押すと以前のセッションのプロンプトが呼び出せる。
      --resume [<id|name>]
                         保存済みセッションを id、一意な id 接頭辞または
                         名前で再開する（`session list` 参照）。値なしでは
                         起動時にセッションピッカーを開く；-p と併用時は
                         ターゲット必須（履歴がワンショットをシードし、
                         回答は行に書き戻される）。--resume=<id> 形式も
                         可。--continue とは併用不可。
      --worktree [<name>]
                         セッション全体を git worktree
                         main-<name>（ブランチ candy-code/<name>）内で実行。
                         初回使用時に作成；名前省略時は自動選択。
                         終了時、コミットも編集もない worktree は
                         削除される；作業が残る場合は保持され、パスを
                         作業は残存し、パスを通知。拒否
                         git ワークツリーの外側で、`serve` の隣です。
      --incognito        何も保存しない起動：セッション行なし、
                         履歴なし、ターン終了時の自動メモリ書き込みなし。
                         実行結果はプロセス内にのみ存在；
                         以前に保存されたセッションやノートは読み取り可能。
                         --continue や --resume との併用は拒否（これらは
                         保存済みセッションを再開するため）。
      --restricted       コード実行不可の起動：Bash、PtyRun、Task、
                         Workflow、ShellStop、mcp_call が
                         セッション全期間でモデル向けセットから除外され、
                         /permissions でも復元不可。ファイルツールは
                         既存のパス制約下で残る。--restricted=true|false
                         形式も可。ラッパーがベアフラグ付きエイリアスを
                         上書き可能。再起動後も維持。
      --safe-mode        すべての信頼を無視する起動：信頼済み
                         プロジェクトルートはすべて非信頼扱い（フック、プロジェクト
                         MCP、コマンドシェル）、バンドル読み込みなし、
                         外部スキル・コマンド・エージェントの検出なし。
                         ネイティブ設定・スキル・コマンドは残る。
                         --safe-mode=true|false 形式も可（エイリアスを
                         上書き）。再起動後も維持。
  -h, --help             このヘルプメッセージを表示
  -v, --version          インストール済みバージョンを表示して終了
      --                 オプション終了：以降の引数はすべて位置引数、
                         フラグではない

環境変数：
   CANDY_CODE_PROVIDER    使用するプロバイダ：openai, anthropic, claude-code,
                          sglang, bedrock, vertex, custom
   CANDY_CODE_MODEL       モデル名（プロバイダ既定を上書き；--model が優先）
   CANDY_CODE_PERMISSION_MODE
                          起動時の権限モード、permissionMode 設定キーを
                          上書き（--permission-mode が優先）
   CANDY_CODE_BACKEND_CMD カスタムバックエンドアダプタ用シェルコマンド、
                          PROSE 契約：stdin で JSON 履歴を受け取り、
                          回答テキストを stdout に出力、そのまま使用
                          （両端のみトリム、内部の改行・空行・インデントは
                          すべて保持）。
   CANDY_CODE_BACKEND_CMD_STREAM
                          別の契約での同様のシェルアウト、TOKEN
                          STREAM：1行1トークン、2トークン間の改行は
                          フレーミングとして破棄、空行は回答内の
                          リテラル改行。コマンドが生成するたびに
                          トークン単位でコールバック発火、ただし読み取りループは
                          同期のため、画面はトークンごとではなく
                          最終時に一度だけ再描画。
                          CANDY_CODE_BACKEND_CMD とは双方向で互換性なし — prose
                          ラッパーをこの変数経由で実行すると
                          改行がすべて消え、空行は1つに潰される。
                          両方設定時、CANDY_CODE_BACKEND_CMD が優先。
                          両変数とも、未設定・空・空白のみは
                          不在とみなす。
   CANDY_CODE_DISABLE_PARALLEL_TOOL_CALLS
                          ターン内のツール呼び出しを厳密に1つずつ実行。
                          並行ディスパッチが既定であり、
                          非変更ツールのみグループ化；これはエスケープハッチ。
                          ~/.candy-code/config.json に
                          "parallelToolCalls": false として永続化可能。
   CANDY_CODE_PARALLEL_TOOL_DEADLINE
                          並行グループが実行を許される秒数、超過で
                          残りは kill され失敗呼び出しとして報告
                          （既定 90、1-119 必須；小数は切り捨て）。
                          "parallelToolDeadlineSeconds" として永続化可能。
                          優先順位：この変数、次に永続化キー、
                          デフォルトになる。1-119 以外の値、または
                          数値でないものは設定済みとみなされない —
                          破棄されず、次のソースに
                          フォールバックする。
   CANDY_CODE_ADVISOR_MODEL
                          `Advisor` ツールがセカンドオピニオンを
                          求めるモデル: ツールなしの補完で、通常の
                          呼び出しと同様に課金される。CANDY_CODE_TITLE_MODEL とは
                          異なり、安価なフォールバックはない — 未設定ならツールは
                          一切提供されない。起動時に読み込まれる。
   CANDY_CODE_TITLE_MODEL セッションの初回やり取り後に自動命名する安価モデル;
                          デフォルトはプロバイダのモデル。
   CANDY_CODE_SUMMARY_MODEL
                          コンパクション要約を生成するモデル;
                          デフォルトは会話自身のモデルで、プロンプトキャッシュを
                          再利用する。
   CANDY_CODE_CONTEXT_PRUNING
                          auto, manual, off: /pruning で未選択の場合に
                          セッションがコンテキストを剪定する方法 (デフォルト auto)。
   CANDY_CODE_MAX_COST    この起動の支出上限 (米ドル;
                          小数可; 先頭の "$" は許容;
                          --max-cost が優先)。上限を超過するターンは
                          拒否される。
   CANDY_CODE_CONNECT_TIMEOUT
                          接続フェーズの上限、秒単位 (小数可;
                          デフォルト 15.0)、プロバイダの HTTP
                          転送用。接続確立のみを制限し、
                          リクエスト全体のタイムアウトではない。接続済み
                          ストリーミングサーバーがレスポンスヘッダーを
                          送信するまでの時間は、別途
                          streamHeaderTimeoutSeconds 設定で制御される。
   CANDY_CODE_SEARCH_ENDPOINT
                          組み込み WebSearch ツールが照会する検索 API。
   CANDY_CODE_SESSION_RETENTION_DAYS
                          正の整数日数: 起動ごとに、その期間以上
                          未使用のセッションを削除する。
   CANDY_CODE_SHARE_UPLOAD_URL
                          廃止されたアップロードホスト: /share は
                          一切アップロードしない。設定済みでもローカルエクスポートは
                          生成されるが、応答は明確にキーを拒否し
                          /share serve を案内する。これは自ホストの
                          スナップショットページを candy-code serve 上に公開する。
   CANDY_CODE_WORKTREES_DIR
                          チームメイトごとの git ワークツリーが
                          作成されるベースディレクトリ。
   CANDY_CODE_DISABLE_MOUSE
                          空または 0 以外の値でマウストラッキングを
                          完全に無効化する。
   CANDY_CODE_DISABLE_MOUSE_CLICKS
                          空または 0 以外の値でクリックジェスチャを
                          無視し、ホイールスクロールは維持する。
   CANDY_CODE_DISABLE_PROMPT_CACHE
                          空または 0 以外の値でプロバイダのプロンプト
                          キャッシュブレークポイントを無効化する。
   CANDY_CODE_DISABLE_PROMPT_SUGGESTIONS
                          空または 0 以外の値で、各ターン後のグレーアウト
                          された次メッセージ提案 (→ で採用) を停止する。
   CANDY_CODE_DISABLE_AUTO_MEMORY
                          空または 0 以外の値で、ターン後に永続的事実を
                          メモとして保存する自動メモリ、および
                          コンパクションジャーナルをそれらに折り込む
                          ドリームパスを停止する。
   CANDY_CODE_DISABLE_MODEL_METADATA
                          空または 0 以外の値で、組み込み数値のないモデルの
                          サイズと価格を決定する LiteLLM モデルデータベースの
                          読み込み・更新を停止する。
   CANDY_CODE_NO_UPDATE_CHECK
                          空または 0 以外の値で、日次の phar リリース
                          チェックと、そこから供給される起動時更新通知を停止;
                          プロセスからリクエストは出ず、古いキャッシュ
                          通知も描画されない。
   CANDY_CODE_DISABLE_SYMBOL_MAP
                          空または 0 以外の値で、ランキング付きシンボルマップを
                          システムプロンプトから除外する。
   CANDY_CODE_BACKGROUND  light または dark — 適応テーマが端末背景について
                          推定する値を強制し、OSC 11 プローブと
                          COLORFGBG をスキップする。
   CANDY_CODE_DEBUG_SKILLS
                          空または 0 以外の値で、SkillLoader の
                          スキップごと・拒否ディレクトリごとの行を
                          stderr に出力する。
   CANDY_CODE_DEBUG_COMMANDS
                          空または 0 以外の値で、CommandLoader の
                          検出拒否行を stderr に出力する。
   CANDY_CODE_DEBUG_RULES 空または 0 以外の値で、RuleLoader の
                          検出拒否行を stderr に出力する。
   CANDY_CODE_DEBUG_STREAM
                          空または 0 以外の値で、Chat の
                          "onToken observer threw" 行を stderr に残す。
                          デタッチ自体はどちらの場合も実行される。
   CANDY_CODE_SERVER_HOST `serve` がバインドするアドレス（--host が優先）。
   CANDY_CODE_SERVER_PORT `serve` がバインドするポート（--port が優先）。
   CANDY_CODE_SERVER_ALLOWED_ORIGINS
                          `serve` が受け付けるカンマ区切りの追加オリジン
                          （--allowed-origin が優先）。
   CANDY_CODE_SERVER_ALLOWED_HOSTS
                          `serve` が応答するカンマ区切りの追加ホスト名
                          （--allowed-host が優先）。
   CANDY_CODE_SERVER_ALLOWED_IPS
                          `serve` が許可するカンマ区切りのクライアントIPまたはCIDR
                          （ループバック以外；--allowed-ips が優先）。
   CANDY_CODE_SERVER_WEB_ROOT
                          `serve` がWeb UIを配信するディレクトリ（--web-root
                          が優先）。
   CANDY_CODE_SERVER_TOKEN
                          `serve` が要求するトークン（状態ディレクトリ内の
                          トークンの代わりに；32文字以上；コンテナ
                          用）。
   CANDY_CODE_SERVER_DIR  `serve` がトークン、ロック、
                          検出レコード、ログを保存するディレクトリ（デフォルト
                          ~/.candy-code/server；0700で作成）。
   CANDY_CODE_SERVER_PARENT_PID
                          `serve` が停止するプロセス（--parent-pid が優先）。
   CANDY_CODE_MCP_DISABLE
                          1、true、yes（大文字小文字無視）でプロジェクトの
                          MCPを完全に無効化：.mcp.jsonは存在しないものとして
                          扱われ、サーバーは起動しない。未設定、0、その他の値は
                          MCPを有効に保つ。フラグ形式の環境変数と異なり、
                          この3つの値のみが有効。
   CANDY_CODE_QUIET_LOGS  1、true、yes（大文字小文字無視）で
                          error_log() サイドチャネルをプロセス全体で
                          沈黙させる（単一のシンク）；未設定、0、その他の値は
                          診断出力を維持。起動時のみ有効、設定キーなし。
   CANDY_CODE_REDUCED_MOTION
                          1、true、yes（大文字小文字無視）でエージェントの
                          スピナーを静止フレームに固定（モーションに敏感な
                          ユーザー向け）。起動時に一度読み込み；
                          設定キーは存在しない。
   CANDY_CODE_SD_BASE_URL メディア転送が接続するA1111スタイル（sdapi）Stable
                          DiffusionサーバーのベースURL。
                          優先順位：明示的なコード上書き、次にこの
                          変数、次に sd.baseUrl 設定。
   CANDY_CODE_MEDIA_RENDER_MODE
                          生成画像をターミナルに描画する方法
                          （ui.imageRenderMode 設定の環境変数レイヤー；
                          許容値は docs/ENVIRONMENT.md 参照）。
   CANDY_CODE_ALLOW_ROOT_TESTS
                          candy-code のテストスイートを root で実行するには
                          正確に 1 に設定；未設定やその他の値では、スイートは
                          euid 0 で起動を拒否。candy-code の起動自体には
                          影響しない — テストスイートはユーザー向け
                          機能ではない。
   CANDY_CODE_TOOL_INPUT  現在のユーザースクリプトツール呼び出しの全引数マップを
                          JSONエンコードし、~/.candy-code/tools
                          ツールの各実行の子プロセスにエクスポート；アプリは
                          これを書き込むだけで読み戻さず、
                          手動で設定するものでもない。
   CANDY_CODE_OTEL_BATCH_SIZE
                          OTLPエクスポート1バッチに含めるスパン数
                          （デフォルト64、1..2048にクランプ）。
   CANDY_CODE_OTEL_TIMEOUT
                          OTLPエクスポート1回の試行の最大秒数
                          （デフォルト3；非正値または不正な値は
                          デフォルトにフォールバック）。

   docs/ENVIRONMENT.md にこのビルドが読み込む全変数と
   その完全な仕様を記載。

終了コード（one-shotモードおよび全サブコマンド）：
  0                      プロンプトが実行され回答を生成、または
                         サブコマンドが正常に応答
  1                      実行したが失敗：バックエンドが例外（到達不能なホスト、
                         拒否されたキー、モデルエラー）— 再試行で解決の可能性 — または
                         サブコマンドが実行され失敗（doctor チェックが
                         FAIL、`session` 動詞で該当セッションが見つからない、
                         信頼済みの .mcp.json が解析不能）
  2                      使用法または設定エラー、何も実行されず
                         再試行しても解決しない：プロンプト未指定、
                         未認識のフラグ、存在しないディレクトリを指す
                         裸の引数（プロンプトには -p が必要）、--root が
                         ディレクトリを指さない、composer の
                         autoload.php が見つからない、選択されたプロバイダが
                         構築不能 — $CANDY_CODE_PROVIDER または
                         Ctrl+P「モデル切替」で ~/.candy-code/config.json に
                         永続化されたプロバイダのいずれか。
                         one-shot実行では、プロバイダが明示的に選択されている場合
                         オフラインechoプロバイダへのフォールバックは行わない。
                         サブコマンドに未指定または未知のオペランドが
                         渡された場合（`session`、`mcp bogus`、`completion tcsh`）も
                         ここに該当する。
  130/143/129             TUI: シグナルによりループが停止 — 128+N（
                         SIGINT (Ctrl+C)、SIGTERM、SIGHUP；協調的
                         終了 (/exit, q) は引き続き exit 0。

例:
  candy-code -p "Explain the difference between require and include"
  CANDY_CODE_PROVIDER=anthropic CANDY_CODE_MODEL=claude-sonnet-4-20250514 \
    candy-code -p "Write a hello world in Go"
  candy-code run "Write a hello world in Go"
  candy-code doctor
  candy-code models --output-format json | jq '.result.providers'
  eval "$(candy-code completion bash)"
  candy-code serve --port 7420

詳細は README を参照:
  https://github.com/detain/sugarcraft/tree/master/candy-code

