    'cli.refuse.max_cost_env' => '$CANDY_CODE_MAX_COST が \'{value}\' に設定されているが、支出上限として不正。正の米ドル数（小数可、先頭の $ 許容）を指定してください。例: 5 または $2.50。ゼロと負値は「上限なし」とは解釈しません（逆の要求のため）。表現不能な値（1e309、すなわち無限大）も拒否（発動しない上限をインストールするため）。上限なしにするには変数を未設定にしてください。要求した上限で無制限実行を拒否し、起動しない。',
    'cli.refuse.max_cost_flag' => '--max-cost が \'{value}\' に設定されているが、支出上限として不正。正の米ドル数（小数可、先頭の $ 許容）を指定してください。例: 5 または $2.50。ゼロと負値は「上限なし」とは解釈しません（逆の要求のため）。表現不能な値（1e309、すなわち無限大）も拒否（発動しない上限をインストールするため）。上限なしにするにはフラグを削除してください。要求した上限で無制限実行を拒否し、起動しない。',
    'cli.refuse.max_cost_setting' => '設定の maxCostUsd が {value} だが、支出上限として不正。正の米ドル数を指定してください。例: 5 または 2.5。上限なしにするにはキーを削除してください。要求した上限で無制限実行を拒否し、起動しない。',
    'cli.refuse.max_turns_flag' => '--max-turns が \'{value}\' に設定されているが、ステップ上限として不正。正の整数（ツールループステップ数）を指定してください。例: 8。ゼロは「上限なし」とは解釈しません（逆の要求のため）。表現不能な値も拒否（発動しない上限をインストールするため）。フラグを削除すると maxToolSteps 設定に従います。要求した上限で無制限実行を拒否し、起動しない。',
    'cli.refuse.no_home' => 'このプロセスはユーザーのホームディレクトリを特定できない（$HOME 未設定、$USERPROFILE 未設定、uid に対応する passwd エントリなし）。~/.candy-code 内の権限ポリシーとフックチェーンを特定できない。全ユーザー書き込み可能なフォールバックディレクトリから読み取ることを拒否し、起動しない。HOME をこのセッションのアカウントに設定してください。',
    'cli.refuse.no_project_root' => 'プロジェクトルートを特定できない — プロセスの作業ディレクトリが利用不可（削除済みまたは読み取り不可）。--root <dir> を指定してください。',
