    'cmd.mcp-auth.heading' => '**MCP Servers**',
    'cmd.mcp-auth.login-armed' => "↻ `{server}` の MCP ログインを開始 — ブラウザリンクを待機中。\n\n子プロセスがループバックポートをバインドします。TUI の応答性を保ちつつブラウザで完了してください。このセッションの MCP クライアントは起動時にストアをメモ化しているため、トークンは次回起動時に有効になります。保存後、`/mcp list` に認証情報が表示されます。",
    'cmd.mcp-auth.login-busy' => '! `{server}` のログインが既に実行中です — まずそれを完了またはキャンセルしてください (URL とステータスは上のトランスクリプトにあります)。',
    'cmd.mcp-auth.login-code-delivered' => '✓ `{server}` の待機中ログインにコールバックを配信しました — 子プロセスがそこで交換を完了し、結果がトランスクリプトに表示されます。',
    'cmd.mcp-auth.login-code-refused' => '! `{server}` の MCP ログインコールバックを配信できませんでした: {reason}',
    'cmd.mcp-auth.login-code-reason-dial' => "待機中ログインのリスナーが応答しませんでした",
    'cmd.mcp-auth.login-code-reason-host' => 'ループバックホスト `127.0.0.1` と `localhost` のみ受け付けます',
    'cmd.mcp-auth.login-code-reason-noslot' => 'このホストで該当サーバーのログインは現在待機していません',
