    'cmd.mcp-auth.login-code-reason-shape' => '形式は `/mcp login <server> --code <callback-url>` で、URL は正確に 1 つです',
    'cmd.mcp-auth.login-done' => '✓ `{server}` の MCP ログインが完了しました (終了コード {code})。トークンは次回起動時に付与されます — 新セッションを開始してリクエストに載せてください。`/mcp list` でパネルが更新されます。',
    'cmd.mcp-auth.login-failed' => <<<'TXT'
✗ `{server}` の MCP ログインが終了コード {code} でトークンを保存せずに終了しました。

子プロセスの最終行は上にあります。同じフローをシェルで実行 (`candy-code mcp auth login {server}`) すると完全なエラーが表示され、エンドポイントやポートの問題をデバッグできます。
TXT,
    'cmd.mcp-auth.login-failed-spawn' => "✗ `{server}` の MCP ログイン子プロセスを起動できませんでした。\n\nシェル形式を直接実行してください: `candy-code mcp auth login {server}`。",
    'cmd.mcp-auth.login-guidance' => "対話型ログインはシェルコマンドであり、チャットターンではありません:\n\n  candy-code mcp auth login <server> [token-url] [authorize-url] [registration-url]\n\nPKCE付きOAuth認可コードフローを実行します。ブラウザが\nコードをシェル内のループバックリスナーに返し、保存された\nトークンは次回起動時に一致するhttpサーバーに付与されます。",
    'cmd.mcp-auth.login-no-entry' => "✗ `mcp auth login {server}` をフォークするための本プログラムのエントリポイントが見つかりませんでした。\n\nシェル形式で直接実行してください: `candy-code mcp auth login {server}`。",
    'cmd.mcp-auth.login-served-armed' => "↻ `{server}` のMCPログインをSERVERホストで開始しました — リンクは下記に表示されます。自分のマシンでブラウザを開いてください。ブラウザはサーバーのループバックリスナーに直接到達できません: 接続エラーページに遷移したら、そのページのアドレスをコピーし、`/mcp login {server} --code <that-url>` を送信してコールバックを待機中のログインに渡してください。トークンは次回起動時に付与されます。保存後は `/mcp list` に資格情報が表示されます。",
    'cmd.mcp-auth.login-url' => '→ `{server}` の認可にこのURLを開いてください:\n\n  {url}',
    'cmd.mcp-auth.not-found' => '! `{server}` の資格情報が見つかりません。',
    'cmd.mcp-auth.registered' => <<<'TXT'
✓ `{server}` の登録に成功しました
クライアントID: `{client}`
このURLと完全一致するhttp MCPサーバーへのリクエストには、今後このトークンが自動的に付与され、期限切れ前にリフレッシュされます。このコマンド実行前に起動したサーバーは次回起動時に取得します。
TXT,
    'cmd.mcp-auth.remove-usage' => '使い方: mcp auth remove <server>',
    'cmd.mcp-auth.reconnect.auth' => '! `{server}` がOAuthログインを必要としています。',
    'cmd.mcp-auth.reconnect.denied' => '! `{server}` はdenyパターンにより拒否されています。',
    'cmd.mcp-auth.reconnect.drifted' => "起動後にMCP設定が変更されました — 再接続は拒否されます。再接続は `.mcp.json` の現在の状態どおりにサーバーを再起動しますが、このセッションは起動時に信頼されたバイト列で承認されています。ドリフトしたエントリの起動は承認判断が及ばないサーバーを実行することになります。変更を適用するにはセッションを再起動してください。これが唯一の適用経路です。",
    'cmd.mcp-auth.reconnect.error' => '起動に失敗しました: {error}',
    'cmd.mcp-auth.reconnect.heading' => '**Reconnected MCP servers**',
    'cmd.mcp-auth.reconnect.no-client' => 'このセッションにMCPクライアントはありません — 再接続対象なし（起動時に `.mcp.json` が信頼されていません）。',
    'cmd.mcp-auth.reconnect.none' => 'このセッションではサーバーが起動していません',
    'cmd.mcp-auth.reconnect.refused' => '! `{server}` は承認時に拒否されました（信頼ピン不一致または不明なエントリ）。',
    'cmd.mcp-auth.reconnect.state.down' => '停止',
    'cmd.mcp-auth.reconnect.state.starting' => '起動中',
    'cmd.mcp-auth.reconnect.state.up' => '稼働',
    'cmd.mcp-auth.reconnect.tool-drift' => '{now} 個のツールを提供中。このセッションは {was} 個で構築されました — モデル向けツール一覧はセッション途中で再構築されません。採用するには新しいセッションを開始してください',
    'cmd.mcp-auth.reconnect.unknown' => 'このセッションには `.mcp.json` の起動時ダイジェストが記録されていないため、再接続時に設定が起動時のバイト列を保持していることを証明できません — 拒否。再起動が唯一の適用経路です。',
    'cmd.mcp-auth.removed' => '✓ `{server}` の資格情報を削除しました',
    'cmd.mcp-auth.status.active' => '● アクティブ',
    'cmd.mcp-auth.status.expired' => '○ 期限切れ',
    'cmd.mcp-auth.status.expiring' => '● 期限切れ間近',
