    // --- fix-app-launch 2026-10-14 ---
    'appLaunch.doctor.mbstring_missing' => '未検出 — フレーム幅計算（mb_*）が実行できません。ext-mbstring付きでPHPを再インストールしてください',
    'appLaunch.doctor.intl_missing' => '未検出 — grapheme/IntlChar幅計算が実行できません。ext-intl付きでPHPを再インストールしてください',
    'appLaunch.notice.policy_changed' => '⚠ 前回起動以降に config.json または hooks.yaml が変更されました。新規プロジェクトフックはこの起動のみ隔離されます — ~/.candy-code/config.json と hooks.yaml を確認後、有効になります',
    'appLaunch.notice.project_policy_changed' => '⚠ 信頼済みプロジェクトの hooks.yaml に前回起動で未確認のエントリがあります。新規プロジェクトフックはこの起動のみ隔離されます — 当該リポジトリの .candy-code/hooks.yaml を確認後、有効になります',
    'appLaunch.notice.bypass_mode' => '⚠ 権限モードが bypass-permissions です: 全ツール呼び出しがプロンプトなしで実行されます。/permissions（TUI）、--permission-mode、または ~/.candy-code/config.json で変更してください',
    // C-SEC-7.a: `-p` now defaults to the ASKING mode, so an unattended scripted
    // run that named no mode starts refusing — the launch says so once, and names
    // the one-flag fix. No trailing period — STDERR_LINE_FORMAT adds one
    // (LaunchNoticeOwnPeriodTest).
    'appLaunch.notice.headless_default' => 'ℹ -p は権限モード default で開始: 無人実行では確認を要するツール呼び出しを全て拒否します。スクリプト実行には --permission-mode を指定してください（bypass-permissions は全実行）',
    // C-SEC-7.e (owner ruling t212, option 3): the implicit autoReview default
    // announces once per session the first time it engages — de-duped by message
    // identity in the launch-notices store, like the bypass banner. Names the
    // opt-out and owns up to the money. No trailing period — STDERR_LINE_FORMAT
    // adds one (LaunchNoticeOwnPeriodTest).
    'appLaunch.notice.auto_review_default' => '⚠ autoReview はこの起動でデフォルト有効: フラグ付きauto-mode呼び出しはタイトルモデルでレビューされ、各レビューは有料モデル呼び出しです。~/.candy-code/config.json で autoReview を false に設定して無効化できます',
    // C-SEC-6.b: names the file, what it added, and what could not be honoured.
    // No trailing period — STDERR_LINE_FORMAT adds one (LaunchNoticeOwnPeriodTest).
    'appLaunch.notice.project_narrowing_rules' => '⚠ {file} によりこの起動の権限が制限されました: {count} 件の deny/ask ルールを優先読込、{dropped} 件の allow ルールを破棄 — プロジェクトファイルは allow を付与できません',
    'appLaunch.notice.restricted' => '⚠ --restricted: この起動はコード実行ツールなしで動作 — Bash、PtyRun、Task、Workflow、ShellStop、mcp_call は全モデル向けセットから除外; ファイルツールはパス制約下に残り、/permissions で除外ツールを復元できません',
    'appLaunch.notice.safe_mode' => '⚠ --safe-mode: 信頼済みプロジェクトルート、バンドル、外部スキル・コマンド・エージェントはこの起動で全て無視 — 何も信頼されていないかのように動作',

    // --- fix-w2-chat 2026-10-14 ---
    'chat.launch.echo_backend' => 'プロバイダーが未設定のため、このセッションは内蔵オフラインエコーバックエンドで動作 — 応答はローカルでエコーされ、モデル呼び出しはありません。`candy-code doctor` を実行してプロバイダー要件を確認し、設定後に Ctrl+P でモデルを切り替えてください。',
    'keys.chat.repaint' => '画面をクリアしてフレームを再描画',
    'keys.unbound' => '未割当',

    // --- C-EXT-1 (Claude Code hook dialect) 2026-10-27 ---
    'hooks.notice.advisory' => '⚠ `async` Claude Code フック `{hook}` が {code} で終了しました。`async` フックはツール呼び出しの監視を求め、ゲートしないためブロック権限がなく、呼び出しは続行されました。出力: {reason}',
    'hooks.notice.claude_dialect' => '⚠ Claude Code フック `{hook}` が {code} で終了しました。Claude Code はこれを非ブロッキングの苦情と解釈し決定ではないため、ツール呼び出しは続行されました。出力: {reason}',
    'hooks.notice.said_nothing' => '（stderr出力なし）',
    'hooks.notice.system_message' => '⚠ フック `{hook}` がメッセージを残しました: {message}',

    // --- C-EXT-6.c (type: http hooks) 2026-10-30 ---
    // Every row names the hook and scheme://host only: never a path, a query,
    // or any header value, so an Authorization cannot ride out of the process
    // inside its own refusal.
    'hooks.http.deny_bad_url' => 'HTTP フック `{hook}` に使用できない URL が設定されています ({reason}); 対象は {target} です。行き先を明示できないフックはこの呼び出しを承認していません。',
    'hooks.http.deny_scheme' => 'HTTP フック `{hook}` は {target} を指定していますが、http または https の URL ではありません。candy-code はこの 2 スキームのみでフックを呼び出し、未検証のトランスポートへの実行は拒否します。',
    'hooks.http.deny_credentials' => 'HTTP フック `{hook}` の URL に認証情報が含まれています ({target})。URL にパスワードを書くとログやプロキシに残るため拒否します。代わりに `allowedEnvVars` の値をヘッダーとして送信してください。',
    'hooks.http.deny_blocked_target' => 'HTTP フック `{hook}` に問い合わせできません: {reason} ({target})。プライベートおよびリンクローカルアドレスはアウトバウンド取得と同じルールで拒否されます。到達できなかったガードはこの呼び出しを承認していません。',
    'hooks.http.deny_unanswered' => 'HTTP フック `{hook}` が応答しませんでした ({reason}); 対象は {target} です。到達できなかったフックはこの呼び出しを承認していないため、拒否されます。',
    'hooks.http.deny_header_injection' => 'HTTP フック `{hook}` は `{field}` ヘッダーを送信できません: 名前または値に制御文字が含まれており、ヘッダー値ではなくリクエストのフレームングです。{target} には何も送信されず、呼び出しは拒否されます。',
    'hooks.http.notice_unanswered' => '⚠ HTTP フック `{hook}` が応答しませんでした ({reason})。このため呼び出しをゲートできませんでした。問い合わせ先は {target} です。',
    'hooks.http.reason_unreachable' => '接続またはリクエストがフック側のタイムアウト内で超過しました',
    'hooks.http.reason_oversized' => 'レスポンスが {bytes} バイトを超え、途中で終わりました',
    'hooks.http.reason_no_status' => '応答に HTTP ステータスラインがありませんでした',
    'hooks.http.reason_redirect' => 'リダイレクトが発生しましたが、フック呼び出しはリダイレクトを追跡しません',
    'hooks.http.reason_status' => '応答が 2xx ステータスではありませんでした',


    // --- C-EXT-6.d (type: prompt hooks) 2026-10-31 ---
    // Nothing was dialled and nothing was spent when these fire, so no row
    // carries a {target}: the hook either has no backend to be asked on, or
    // the answer it got is not a verdict.
    'hooks.prompt.deny_unanswered' => 'プロンプトフック `{hook}` が応答しませんでした ({reason})。判定が返されなかったフックはこの呼び出しを承認していないため、拒否されます。',
    'hooks.prompt.notice_unanswered' => '⚠ プロンプトフック `{hook}` が応答しませんでした ({reason})。このため呼び出しをゲートできませんでした。',
    'hooks.prompt.reason_call_failed' => 'モデルに問い合わせできませんでした',
    'hooks.prompt.reason_empty_verdict' => 'プロンプトフック `{hook}` は理由を述べずにこの呼び出しを拒否しました。',
    'hooks.prompt.reason_no_backend' => 'この起動には問い合わせ先のタイトルモデルがありません',
    'hooks.prompt.reason_no_prompt' => 'エントリのプロンプトが空です',
    'hooks.prompt.reason_unparseable' => '応答が、要求された boolean `ok` を持つ単一の JSON オブジェクトではありませんでした',

    // --- settings help (W3-B i18n migration) ---
    'settings.advisorModel.help' => '`Advisor` ツールがセカンドオピニオン用に参照するモデル。未設定（デフォルト）ではツール自体が提供されません（安価モデルへのフォールバックはありません: 重要なのは自分で選んだモデルであることです）。',
    'settings.allowedTools.help' => 'ツール名またはグロブのホワイトリスト; 未設定ではすべてのツールが提供されます。',
    'settings.attribution.help' => '{"commit": "…", "pr": "…"}: git ガイダンスが要求するトレーラーと PR 行。',
    'settings.autoCommit.help' => 'off、turn（1 ターンにつき 1 コミット、メッセージはタイトルモデルから取得）または edit（Write/Edit ごとに 1 回）; /undo で元に戻せます。',
    // C-SEC-7.e (owner ruling t212, option 3): the help states the implicit
    // default, the once-per-session announce, and the paid-call fact.
    'settings.autoReview.help' => 'auto では、安全分類器がフラグを立てた呼び出し（セキュリティ上の指摘は常に確認を求める）をタイトルモデルがレビューし、許可・確認・拒否のいずれかを行います。レビュー可能なモデルが存在すればデフォルトで有効になり、そのデフォルトが適用される起動では一度だけ通知されます。false に設定するとオプトアウトできます。すべてのレビューは有料のモデル呼び出しです。',
    'settings.autoReviewModel.help' => 'auto レビュアーが実行される `provider/model`、例: `openai/gpt-4.1-mini`; 空文字列はタイトルモデルを意味します。構築できないプロバイダーはレビュアーを無効にし、起動時に警告を出します。',
    'settings.autoReviewScope.help' => '`autoReview` がレビュアーに送信する内容: `shell`（デフォルト）はパターンリストを通過した非読み取り専用 shell コマンドすべて; `writes` は `Edit`、`Write`、`ApplyPatch`、`WebFetch` もレビューし、書き込みツールには保留中の diff を添付; `all` はリストを通過したすべての呼び出しをレビュー。それ以外の表記は `shell` として動作します。すべてのレビューは有料のモデル呼び出しです。',
    'settings.autoTest.help' => 'ファイルを編集したターン後に `testCommand` を実行; 失敗時は出力をモデルに返し、1 ターンにつき最大 3 回まで。',
    'settings.bashInteractiveIdleSeconds.help' => '`interactive: true` の Bash 実行が、キー入力待ちとして停止されるまでの無出力秒数。',
    'settings.bashMaxTimeoutSeconds.help' => 'Bash コマンドが要求できる最大の `timeout`; これを超える値はクランプされます。',
    'settings.bashSandbox.help' => 'Linux では Bash を bubblewrap 内で実行; macOS では `sandbox-exec` 経由で Seatbelt プロファイル内で実行 — 書き込みは作業ルートのみ（`no-network` はネットワークも遮断）。`allowlist`（Linux）はネットワーク送信を起動時の egress プロキシ経由にルーティングし、`sandboxAllowedDomains` に列挙されたホストのみ許可: デフォルトの EMPTY リストではホストを列挙するまで `no-network` と完全に同じ動作、列挙後も非 HTTP トラフィック（ssh、データベースポート）や未列挙ホストは失敗。macOS では `allowlist` は `no-network` として強制。jail の起動に失敗した場合はコマンドを拒否; 認識できない値は `no-network` として扱い、`off` にはなりません。',
    'settings.bashSandboxNestedUserns.help' => '`true` に設定すると、サンドボックス化された `Bash` コマンドが自身のユーザー名前空間を作成できます（rootless podman、buildah、Chromium サンドボックスに必要）。デフォルトの `false` は bubblewrap を `--unshare-user --disable-userns` で実行し、マウント jail からの通常の脱出経路を遮断; これらのフラグに対応しない古い bubblewrap のホストでは、通常のセットで jail を実行し、その旨を説明に明記します。',
    'settings.bashTimeoutSeconds.help' => 'モデルが `timeout` を渡さない場合に Bash コマンドが実行できる秒数; Bash 上限を超えることはありません。',
    'settings.chatToolTimeoutSeconds.help' => 'チャットネイティブ（`command` プロバイダー）パスがフォークするツール呼び出しバッチのウォールクロック予算; 遅延者は kill されます。',
    'settings.claudeMcpArgs.help' => 'そのバイナリへの引数; 未設定ではトランスポートのデフォルトを使用します。',
    'settings.claudeMcpBinary.help' => 'claude-mcp トランスポートが起動できる `claude` バイナリの絶対パス。',
    'settings.claudeMcpEnv.help' => 'そのバイナリに渡されるリテラルな環境変数。',
    'settings.compaction.autoPercent.help' => 'プロンプト送信前に古いやり取りが自動的に圧縮されるウィンドウ占有率。',
    'settings.compaction.autoTokens.help' => '自動ティアとターン内ステップ予算の絶対上限。0 で上限を無効化。',
    'settings.compaction.blockPercent.help' => 'このウィンドウ占有率を超えると、空きが確保されるまでプロンプトが拒否される; 拒否を行う唯一のティア。',
    'settings.compaction.blockTokens.help' => 'ブロッキングティアの絶対上限; デフォルトでは未設定。設定すると上限でプロンプトを拒否できます。',
    'settings.compaction.idleAuto.help' => 'アイドル中のティア超過セッションを、次のプロンプト待ちではなくアイドル中に自動ティアの機構（支出上限とスラッシュブレーカーが適用）で圧縮。off: 行わない; hour: compaction.idleOfferSeconds の全ウィンドウ経過後; cacheTtl: プロバイダーのプロンプトキャッシュ有効期限の直前 — プロバイダーがキャッシュブレークポイントをマークする場合は 1 時間、サーバー側キャッシュでは約 5 分、キャッシュなしを報告する場合は行わない — 履歴が自動ティアよりフロア分超過した時点で、次のプロンプトが会話全体をキャッシュなしでプリフィルするのを防ぐため; 60 秒ティックで 5 分キャッシュは約 4 分アイドルで折り畳み。バックグラウンドのプロバイダー呼び出しが発生; compaction.idleOfferSeconds が 0 より大きいことが必要。bool 値も読み取り可能: true は hour、false は off。',
    'settings.compaction.idleOfferSeconds.help' => 'コンテキストウィンドウ全体を超過したセッションがこの時間触れられていない場合、プロンプト送信の代わりに /compact を提案。0 で提案しない。',
    'settings.compaction.keepRecent.help' => '圧縮時に完全に保持する直近のユーザー/アシスタントやり取り数。',
    'settings.compaction.mode.help' => 'llm: 要約モデルが要約を作成（ヒューリスティックはフォールバック）; heuristic: ローカルな 1 行要約、モデル呼び出しなし; off: 自動圧縮なし、/compact は動作し、ブロッキングティアは引き続き拒否。',
    'settings.compaction.modelTokenCaps.help' => '{"<model>" または "<provider>/<model>": {"reminderTokens", "autoTokens", "blockTokens"}} で 3 つの上限を上書き; 0 で 1 つをクリア。',
    'settings.compaction.refillLimit.help' => '連続でティア上限を即座に超過する自動圧縮の回数; これを超えると次のプロンプトは圧縮ではなく拒否されます。',
    'settings.compaction.reminderPercent.help' => '「圧縮を検討」リマインダーと事前バックグラウンド要約が開始されるウィンドウ占有率; 自動ティアより下。',
    'settings.compaction.reminderTokens.help' => 'リマインダーティアの絶対上限: min(パーセンテージ, これ) で発火。0 で上限を無効化。',
    'settings.compaction.summaryAssistantChars.help' => 'この長さを超えるアシスタント応答は、ヒューリスティック要約行で "[exchanged information]" になります。',
    'settings.compaction.summaryUserChars.help' => 'ヒューリスティック要約行が保持するユーザーメッセージの文字数。',
    'settings.compaction.toolOutputChars.help' => '圧縮済みやり取りのアシスタント側で要約モデルに表示される文字数。',
    'settings.connectTimeoutSeconds.help' => 'プロバイダーホストへの到達（DNS、TCP、TLS）の上限; リクエストタイムアウトではありません。',
    'settings.contextPruning.compress.help' => 'manual は /compress で開始するターンのみ Compress を提案（1 回呼び出し）; auto はモデルがプルーニング可能なすべてのターンで提案。',
    'settings.contextPruning.iterationNudgeThreshold.help' => '直近のプロンプト以降のツール結果がこの数を超えると、長いツールループにプルーニングをリマインド。',
    'settings.contextPruning.maxContextTokens.help' => 'このコンテキストサイズを超えると、最新行に強い「今プルーニング」リマインダーが付与。',
    'settings.contextPruning.minContextTokens.help' => 'このコンテキストサイズ未満ではプルーニングのリマインドを一切行わない; ハードリマインダーサイズを超えてはならない。',
    'settings.contextPruning.mode.help' => 'auto は各ターン開始時に上書きされた行をプルーニング; manual は /sweep 時のみ; off は ref タグを表示しない。/pruning でセッションごとに上書き。',
    'settings.contextPruning.nudgeFrequency.help' => 'リマインダーが前回から待つ新規行数; 各ステップでの繰り返しを防ぐ。',
    'settings.contextWindow.help' => 'トークンウィンドウの上書き: プロバイダーのモデルに対するカウント数、または {"<model>": tokens}。',
    'settings.debug.commands.help' => '拒否されたカスタムコマンドのディレクトリまたはファイルごとに stderr へ出力; 起動時の 1 行カウントだけでなく個別に表示。',
    'settings.debug.rules.help' => '拒否されたルールのディレクトリまたはファイルごとに stderr へ出力。',
    'settings.debug.skills.help' => 'スキップされたスキルファイルと拒否されたスキルディレクトリごとに stderr へ出力; 起動時の 1 行カウントだけでなく個別に表示。',
    'settings.debug.stream.help' => '埋め込み側のストリーミングシンクがターン途中で失敗したとき、「onToken observer threw, detaching it」行を stderr へ出力。',
    'settings.diffPreviewRows.help' => 'Edit または Write の diff で、残りが要約される前にトランスクリプトに表示される行数。',
    'settings.diffStyle.help' => 'トランスクリプト内の diff レイアウト: `auto` は広いターミナル（120 列以上）でハンクを左右に並べ、それ以外は unified; `unified` は常に 1 列; `split` は常に 2 列。diff 本文はどちらのレイアウトでもトークンごとに色付け; `+`/`-` マーカ列は色を維持。',
    'settings.disabledMcpServers.help' => '`.mcp.json` のサーバー名またはグロブ（`untrusted_*`）で、メインエージェントとすべてのサブエージェントに対して起動・一覧・呼び出しが一切行われないもの。',
    'settings.disabledRules.help' => '最初のターンからプロンプトに含めないユーザーティアのルールパック。',
    'settings.disabledSkills.help' => '検出から除外するスキル; enabledSkills より優先。',
    'settings.disabledTools.help' => 'モデル向けツールセットから除外するツール名またはグロブ。',
    'settings.doubleEscSeconds.help' => '実行中のターンをキャンセルするために、2 回目の Esc が 1 回目から従うべき最大間隔。',
    'settings.embeddingModel.help' => 'ターンごとのメモリリコールに使用する埋め込みモデル; 未設定ではキーワードのみでノートをランク付け。',
    'settings.enabledSkills.help' => '毎ターンシステムプロンプトに全文が載るスキル。',
    'settings.env.diffMaxBytes.help' => 'git diff の 2 セクションそれぞれが、注記付きで切り詰められる前に保持するバイト数。',
    'settings.env.gitDiffAfterWrites.help' => 'ファイルを書き込んだステップ後、ターンコンテキストにステージ済みおよび未ステージの git diff を表示。',
    'settings.expandToolOutput.help' => '完了したツール呼び出しの出力をトランスクリプトに全文表示; Ctrl+O またはクリックで個別に折り畳み可能。',
    'settings.extraBody.help' => 'すべての `custom` プロバイダーリクエストに追加されるトップレベルのリクエストフィールド。',
    'settings.formatCommands.help' => 'ファイル拡張子ごとの編集後フォーマットコマンド（{"php": "vendor/bin/php-cs-fixer fix {file}"}）; 編集後 lint の前に実行され、ファイルを書き換えます。デフォルトで off。',
    'settings.formatAuto.help' => '組み込み拡張子テーブル（gofmt、rustfmt、ruff/black、shfmt、terraform fmt、プロジェクトの node_modules 内 prettier）で、`formatCommands` に該当拡張子のコマンドがない場合の編集後フォーマットを許可。明示的なエントリが優先; プロジェクトには依然として `trustedProjectHooks` が必要。デフォルトで off。',
    'settings.globMaxMatches.help' => 'Glob が走査を停止する前に収集するパス数; 出力上限は引き続き結果を制約します。',
    'settings.grepTimeoutSeconds.help' => 'Grep 検索が kill されるまでの秒数; 期限までに発見されたヒットは部分結果として返されます。',
    'settings.hooksDefaultTimeoutSeconds.help' => '`timeout:` なしのフックエントリが kill され拒否としてカウントされるまでの秒数。',
    'settings.includeGitInstructions.help' => 'Bash ツールの汎用コミットガイダンスをシステムプロンプトに載せるかどうか。',
    'settings.instructions.help' => '内容が権威あるシステムプロンプトテキストになるファイルのグロブ。',
    'settings.instructions.walkToRoot.help' => 'オプトイン: 最寄りの .git マーカーより上の指示ファイルも、ホームディレクトリの手前まで読み取り。ユーザーティアのみ; すべての読み取りは包含とサイズ予算を維持。',
    'settings.instructionsExclude.help' => 'スキップする指示ファイルのグロブ、拒否として記録; ユーザーティアのみ — リポジトリはオペレーターを黙らせることはできない。チェックアウト内のファイルはチェックアウト相対パスで一致; 祖先および強制ファイルはチェックアウト外なので絶対パスで一致、`**/CLAUDE.local.md` は祖先コピーにも届く。',
    'settings.keybindings.help' => '{"shell.palette": "Ctrl+B"}: バインディング ID に追加のコードをバインド（/keys リファレンスで確認可能）— Ctrl+<key>、Alt+<key>、Shift+<key>、または単独のファンクションキー; 出荷時コードは引き続き動作。存在するが使用不能な場合は起動を拒否; 出荷時バインディングのキーを削除してください。',
    'settings.layout.help' => 'ドックペインのマニフェスト; ペイン移動時にシェルが書き込みます。',
    'settings.lintCommands.help' => 'ファイル拡張子ごとの編集後 lint コマンド（{"php": "…", "js": false}）; `php -l` は組み込み。',
    'settings.lsp.help' => '{"php": {"command": "intelephense", "args": ["--stdio"]}}: 編集後診断、Read アウトライン、Lsp ツール用のサーバー。',
    'settings.lspAutoDetect.help' => 'プロジェクトのフィンガープリントが示す言語サーバー（composer.json → intelephense、package.json + tsconfig.json → typescript-language-server、pyproject.toml または setup.py → pyright-langserver、go.mod → gopls、Cargo.toml → rust-analyzer）を、バイナリが PATH 上にあれば自動起動する。言語ごとに手動の `lsp` エントリが優先。サーバー起動はそのサーバーと開いたツリーのビルドコードを実行するため、フィンガープリントはフックを信頼したプロジェクトでのみサーバーを起動する。信頼されていないルートでは起動せず、スキップを起動通知に記録する。',
    'settings.maxCheckpoints.help' => '/rewind で戻れるターンチェックポイント数（セッションごと）。古いものからこの数を超えて削除される。',
    'settings.maxCostUsd.help' => 'プロバイダー報告の支出がこの米ドル額に達した時点で新規ターンを拒否。未設定なら上限なし。/budget は実行中のローンチのみ変更。',
    'settings.maxOutputTokens.help' => 'リクエストごとの出力上限。未設定ならオーバーライドを送らず、プロバイダーのデフォルトが適用される。',
    'settings.maxToolSteps.help' => '1ターンが実行できるプロバイダー呼び出し数。未設定ならエンジンのデフォルトを維持。',
    'settings.mcp.enabled.help' => '信頼済みプロジェクトの .mcp.json が示す MCP サーバーを起動。off は起動せず、サーフェスに無効として表示。',
    'settings.mcp.lazySchemaTokens.help' => '1つの MCP サーバーがツールを mcp_list/mcp_call に委譲する前に広告できるスキーマトークン数。0 は委譲しない。',
    'settings.mcpResultCapBytes.help' => '1つの MCP ツールの回答がモデルに渡せる最大バイト数。',
    'settings.memory.autoConsolidate.help' => '完了したターンから永続的事実をメモリに保存し、圧縮ジャーナルをそこに折り込む（ドリームパス）。各パスは課金呼び出し。',
    'settings.memory.dreamIntervalSeconds.help' => '1プロジェクトで2回のドリームパス間の最小間隔。各パスは課金される読み取り専用ターン。',
    'settings.memory.dreamProposeSkills.help' => 'ドリームパスが ~/.candy-code/skills-proposed にスキルをドラフトとして提案できるようにする。/skills で承認するまで有効にならない。',
    'settings.memory.entryMaxBytes.help' => '1つのノートのインデックス行が切り詰め表示される前の最大長。ユーザーノート予算を超えた場合はそれに引き下げられる。',
    'settings.memory.projectNoteMaxBytes.help' => '1つのプロジェクトメモリノートが .candy-code/memory/ に書き込まれる際の最大サイズ。',
    'settings.memory.promptMaxBytes.help' => 'メモリインデックスのノート行に対するバイト予算。ユーザーノート予算はこれに収まるよう引き下げられる。',
    'settings.memory.promptMaxEntries.help' => 'プロンプトのメモリインデックスが列挙するノート数（新しい順）。ユーザーノートもこの内数に含まれる。',
    'settings.memory.userMaxBytes.help' => 'ユーザースコープ行に対するバイト予算（総予算の内）。',
    'settings.memory.userMaxEntries.help' => 'ノート数の内、最初に列挙されるクロスプロジェクト（ユーザースコープ）ノートの最大数。',
    'settings.modelPrices.help' => 'モデルごとの 1M トークンあたりの USD 単価（{"input": …, "output": …}）。支出合計と上限の計算に使用。',
    'settings.models.help' => 'プロバイダーごとの実行モデル（{"<provider>": "<model id>"}）。未設定ならプロバイダーのデフォルトを使用。',
    'settings.mouse.help' => 'マウス入力を candy-code に報告（クリック、ホイール、選択）。off にするとターミナルの copy-on-select が戻る。',
    'settings.mouseClicks.help' => 'クリックとドラッグが当たった対象に作用する。off にするとホイールは維持しクリックを無視。',
    'settings.notices.transcriptLimit.help' => 'トランスクリプト行として表示する起動警告の最大数。残りは「and N more」行に集約され、stderr に全件出力される。',
    'settings.notify.help' => 'off、bell (BEL) または osc9（デスクトップ通知）：ターン終了時とエージェントが承認待ちの時に送信。',
    'settings.paletteMru.help' => '最近使用したパレット行を記憶して上位に並べる数。0 は記憶しない。',
    'settings.parallelToolCalls.help' => '1ターンの読み取り専用ツール呼び出しを並行実行する。',
    'settings.parallelToolDeadlineSeconds.help' => '並行ディスパッチされたツール呼び出しの1バッチに対する実時間上限。',
    'settings.permissionMode.help' => 'ツール呼び出しのゲート方式。プロジェクトファイルからは取得されない。',
    'settings.permissionRules.help' => '各ツール呼び出しにマッチする順序付き allow / deny / ask ルール。信頼済みプロジェクトの共有 settings.json は deny / ask エントリのみ寄与可能（絞り込みのみ）。',
    'settings.permissions.autoAllowReadOnly.help' => 'default と accept-edits モードで、読み取り専用コマンドのみ（ls、cat、grep、git log、…；ファイルリダイレクトなし、置換なし、cd はプロジェクト内のみ）で構成された Bash 行を承認なしで実行する。プロジェクトはこれを off にすることしかできない。',
    'settings.permissions.autoStrikeLimit.help' => 'auto モードで、同一カテゴリのブロックされた呼び出しがこの数連続すると次を質問に変換する。',
    'settings.permissions.autoTotalLimit.help' => 'auto モードで、セッション内でこの数の呼び出しがブロックされると、以降のブロックは毎回質問になる。',
    'settings.pluginPaths.help' => 'Claude 形式のプラグインバンドルを検索する追加ディレクトリ（インストール済み2ルートとは別に）。値はバンドル自体またはバンドルのコンテナを指す。ユーザーティア限定：チェックアウト先が自前のプラグインを登録することはできない。',
    'settings.promptCache.keepWarm.help' => 'アイドル区間ごとに許可するウォーム ping 数。0（デフォルト）は無効。各 ping はアイドルセッションの凍結プレフィックスを1文字の返信を求める1行の指示付きで再送し、TTL 切れ前にプロバイダーのプロンプトキャッシュを更新して次プロンプトが全会話を未キャッシュでプリフィルしないようにする。cacheTtl フォールドが却下された場合のみ（フロア未満または1時間前）に、フォールドウォッチと同じ tick/alarm で発火。ターン中は発火せず、同時1件まで、この数を超えてはならない。誰も見ていないセッションへの課金呼び出しであり、支出上限は依然として適用される。件数は /usage の `warm` に表示。',
    'settings.promptCache.help' => '`vertex` と `bedrock` プロバイダーがプロンプトキャッシュのブレークポイントをマークするかどうか。',
    'settings.promptSuggestionHistory.help' => 'プロンプト提案呼び出しに渡される直近メッセージ（各2000文字に切り詰め）。',
    'settings.promptSuggestions.help' => '各ターン後、タイトルモデルに次に入力しそうなメッセージを尋ね、空の入力欄にグレーで表示（→ で承認）。',
    'settings.provider.help' => 'セッションが通信する LLM プロバイダー。全プロンプトはそのホストに送信される。',
    'settings.providerRetryAttempts.help' => '一時的失敗（ネットワーク、5xx、408、429）時のプロバイダーリクエストごとの呼び出し数（初回含む）。1 はリトライしない。',
    'settings.providerRetryBaseBackoffMs.help' => '失敗したプロバイダー呼び出しの初回リトライ前の待機時間。以降の待機は倍増する。',
    'settings.providers.help' => '名前ごとのプロバイダー定義（{"<name>": {"type": …, "baseUrl": …, "apiKey": …, "model": …}}）。各エントリはその型のデフォルトに重ねる。ユーザーティア限定：プロジェクトが認証情報の送信先を移すことはできない。',
    'settings.queueMode.help' => 'steer（エージェントが次のステップで読む）、followup（ターン後に送信）または interrupt（次のステップでターンを停止し送信）。Tab は常にキューに追加。',
    'settings.readMaxBytes.help' => '1回の Read 呼び出しの上限。下のページサイズは通常の読み取りで返る量。',
    'settings.readPageBytes.help' => '1つの Read ページが保持できるバイト数（行番号含む）。`limit` の指定に関わらず。',
    'settings.readPageLines.help' => 'Read 呼び出しに `limit` が指定されていない場合に返される行数。',
    'settings.reasoningEffort.help' => 'ペアが形作る箇所に思考ティアを送信: openai (o-series と gpt-5、-chat ビルドは除く), anthropic と vertex (claude-3-7 以降; vertex は claude と gemini の両系統で応答), gemini (2.5 以降), sglang (全リクエストに転送), bedrock (claude ids、思考予算として), codex と claude-code (名前付きティアを CLI に転送); 未設定または未認識の場合は何も要求しない。`/effort` で設定・解除。',
    'settings.redactToolOutput.help' => 'デフォルト off：確定したツール出力は返ってきたまま history と sessions.db に保存される。on にすると、確定した全ツール結果がメモリと `/share` を守るのと同じリダクターを通る — 認識された認証情報は永続バイトと後続ターンでモデルに再生される内容で `[REDACTED]` になる（ツール自体は変更なく実行）。画像、ドキュメント、usage フィールドはそのまま通過。`/export` は独自のリダクションを追加しない：保存されたものをそのまま出力するため、有効化前に保存されたものは生のまま残る。',
    'settings.references.help' => 'ワークスペース外のディレクトリのリスト `[{"path": "…", "name": "…"}]`。Read、Grep、Glob、Ls が読み取り専用で開ける。各ディレクトリは `<env>` ブロックに内容の上限付きマップとして広告される。Write、Edit、Bash に対するワークスペースのジェイルは変わらない — 参照は書き込み可能な範囲を広げない。ユーザーティア限定：チェックアウト先リポジトリが読み取りルートを追加することはできない。存在しないパス、ディレクトリでないパス、セッションルート内のパスは起動時に通知付きで拒否される。',
    'settings.repoMap.enabled.help' => 'コードの所在マップ（パッケージと PSR-4 ソースディレクトリ）をシステムプロンプトに含める。',
    'settings.repoMap.maxBytes.help' => 'リポジトリマップの2セクション各々のバイト予算。超えたエントリは列挙せず件数で示す。',
    'settings.requireReadBeforeWrite.help' => 'on にすると、`Edit`、既存ファイルを上書きする `Write`、変更・移動・削除を行う `ApplyPatch` は、モデルが本セッションでそのファイルを読んでいるまで拒否される。新規ファイル作成は常に許可。デフォルト off：モデルが読んだファイルはどちらの設定でもディスク変更ルールで保護される。',
    'settings.resumeCostWarnUsd.help' => '古い resume 後、履歴の再送が未キャッシュでこの金額以上かかると推定される場合、最初のプロンプトを1回保留する。Enter を再押下で送信、または /compact を先に実行。0 は保留を無効化。',
    'settings.sandboxAllowedDomains.help' => '`allowlist` ジェイルが到達できるホスト：素の名前（`example.com`）、`*.example.com` ワイルドカード、`host:port` 表記（デフォルト：なし）。Linux で `bashSandbox` が `allowlist` の場合のみ使用。リストが EMPTY の場合 `allowlist` は `no-network` と完全に同一の動作。エグレスプロキシは HTTP(S) のみ許可 — 未記載のホストは 403、非 HTTP トラフィック（ssh、DB ポート）は失敗。不正なエントリは強制時に IGNORED：誤字は許可を狭めるだけで広げることはない。ユーザーティア限定：チェックアウト先リポジトリがジェイルに穴を開けることはできない。macOS では `allowlist` を `no-network` として強制 — ループバックポートアームは追跡中のフォローアップ。',
    'settings.sandboxScope.help' => 'ツールパス外で `bashSandbox` ジェイルに参加するコマンド：`hooks`、`lint`、`format`、`test`、`lsp`、`mcp`（デフォルト：なし）。`bashSandbox` が `off` でない間のみ有効 — リストは誰がジェイルを共有するかを示すだけで、ジェイルの有無は示さない。認識されないエントリは EVERY スコープとして読まれ（最も厳格、認識されない `bashSandbox` 値と同様）、設定監査に名前が記録される。起動できないジェイルは作業を拒否し無制限実行はしない：スクリプトフックは deny、lint/format/test は理由付きでスキップ、ジェイル内の LSP または MCP stdio サーバーは起動しない。`lsp` エントリとユーザーティアの MCP エントリはサーバーごとの `"sandbox": false` オプトアウトを持つ。プロジェクトティアの MCP オプトアウトは無視される。',
    'settings.screenReader.help' => 'スクリーンリーダーユーザー向け表示。on にすると、リーダーが読み上げられない装飾を除去 — エージェントスピナーは1静的フレームに固定、ボックス描画フレーム、反転表示のみメニュー選択などはプレーンテキストと各サーフェスの切替時の音声キューに置き換わる。off は通常のペイント済みターミナル。自分のアクセシビリティ設定（ドラフトボックスの vim モードと同様）：チェックアウト先プロジェクトが変更することはできない。保存後の次回の読み取りで適用 — リロード不要。',
    'settings.rules.standingMaxBytes.help' => '全プロンプトにそのまま挿入されるルールファイルの、枠付き・エスケープ済みバイト予算。超えたルールは1行のポインターで示される。',
    'settings.scrollWheelLines.help' => 'ホイール1クリックでスクロールするトランスクリプト行数。',
    'settings.sd.apiKey.help' => 'Stable Diffusion サーバーに送る Bearer キー（要求する場合）。リテラルより `${VAR}` プレースホルダー形式を推奨。',
    'settings.sd.baseUrl.help' => 'AUTOMATIC1111 互換 Stable Diffusion webui の HTTP ベース URL（`http://127.0.0.1:7860`）。プロンプト、画像、API キーがすべてここに送出される。',
    'settings.sd.defaultModel.help' => '生成リクエストが最初に使うモデル ID。未設定ならサーバーが選択を保持する。',
    'settings.sd.presets.help' => 'メディアフォームが提供する名前付きパラメータバンドル。形状はメディアパイプライン固有で、設定層からは不透明。',
    'settings.sd.savePattern.help' => '保存メディアのファイル名テンプレート。`[date]`、`[time]`、`[seed]`、`[number]` トークンは保存時に展開される。',
    'settings.sd.timeoutSeconds.help' => '1つの生成リクエストが中断されるまでの最大秒数。弱い GPU での拡散は数分かかるのが普通。',
    'settings.secretEnvAllowlist.help' => 'Bash、Grep、スクリプトフックが依然として継承する認証情報風の環境変数名（または glob）。',
    'settings.server.allowBypass.help' => 'サーバーセッションが bypass-permissions または dont-ask で実行できるか（--allow-bypass と同等）。',
    'settings.server.allowedHosts.help' => 'ループバック名と自身のアドレス以外でサーバーが応答するホスト名（または host:port）。例：リバースプロキシのホスト。',
    'settings.server.allowedIps.help' => 'ループバック以外で接続を許可するクライアント IP または CIDR 範囲。それ以外はサインイン前に 403 で拒否。空：アドレスフィルタなし。',
    'settings.server.allowedOrigins.help' => 'サーバーが自身のもの以外に受け入れる追加ブラウザオリジン（http(s)://host[:port]）。',
    'settings.server.askTimeoutSeconds.help' => '権限質問がクライアントの応答を待つ秒数。0 は無限待ち。',
    'settings.server.browseRoot.help' => 'server.dirBrowse が制限されるディレクトリ（--browse-root と同等）。未設定ならホームディレクトリ。',
    'settings.server.dirBrowse.help' => 'サインイン済みクライアントが server.browseRoot 配下のディレクトリ名を一覧し、そこでセッションを開始できるようにする（--allow-dir-browse と同等）。デフォルト off。',
    'settings.server.clientTools.help' => 'Write スコープのクライアントが tools.client.register 経由でツールを登録し、モデルがクライアント自体で実行されるコードを呼び出せるようにする（client__* ツール）。デフォルト off。',
    'settings.server.drainSeconds.help' => '停止中のサーバーが実行中ターンをキャンセルする前に待つ秒数。0 は即停止。',
    'settings.server.host.help' => '`serve` がバインドするアドレス。ループバック以外には起動時に --allow-remote も必要。',
    'settings.server.maxConcurrentTurns.help' => 'サーバーがセッション全体で同時に実行するターン数。超えると busy で拒否（リトライ可）。',
    'settings.server.maxOpenSessions.help' => 'サーバーが同時に開いておくセッション数。超えると最も古いアイドルセッションが解放される。',
    'settings.server.port.help' => '`serve` がバインドするポート。0 は空きポートを自動選択。',
    'settings.server.trustedProxies.help' => 'サーバーが X-Forwarded-For / X-Forwarded-Proto を信頼する IP または CIDR。',
    'settings.serviceTier.help' => 'ペアが形作る箇所に送られるプレミアムレーン：openai は Chat と Responses 両アームで `service_tier: "priority"` を要求、anthropic は `speed: "fast"` を要求（claude-opus-5-5 GA 系と claude-opus-5 / claude-opus-4-8 research-preview 系のみ、必須 beta ヘッダーは自動付与）。未設定または不明な場合は何も要求しない。Fast モードはモデル別価格表から導出できないプレミアムを課金：ティア付きペアが有効な間、ターンは未価格として台帳に記録され、推定レートにはならない。ローンチ時と全プロバイダー/モデル再構築時に適用。',
    'settings.sessionRetentionDays.help' => '各ローンチで、この日数以上触られていない無名・未ピン留めセッションを削除し対象を通知。0（デフォルト）は全保持。',
    'settings.sessions.autoTitle.help' => 'タイトルモデルへの1回の呼び出しで各新規セッションを最初のターンから命名。off は /rename まで無名のまま。',
    'settings.sessions.awayRecap.help' => '3分以上離席後にフォーカス復帰が報告されると、セッションの中断地点を1回だけ要約表示（不在ごとにタイトルモデルを1回呼び出し）。off なら復帰時は無音。`/recap` でいつでも要約をリクエスト可能。',
    'settings.skills.listingMaxBytes.help' => 'システムプロンプト内の全スキル一覧に対するバイト予算。超えたスキルは「N more skills」1行に集約。',
    'settings.skills.pathNudges.help' => 'ツールがパススコープのスキルがカバーするファイルに触れた際、そのスキルの存在をモデルに1回リマインドする。',
    'settings.statusLine.help' => '{"type": "command", "command": "…", "refreshSeconds": 2}：出力でステータスバーを描画するシェルコマンド。refreshSeconds ごと（2〜3600、デフォルト 2）に再実行。stdin でセッションを JSON ドキュメントとして受け取る（session_id、cwd、model、workspace、version、cost、candy_code 追加項目）。stdin を読まないコマンドも実行される。',
    'settings.streamHeaderTimeoutSeconds.help' => '接続済みストリーミングサーバーがレスポンスヘッダーを送るのに許される秒数。リクエスト全体のタイムアウトではない。',
    'settings.streamIdleTimeoutSeconds.help' => 'ストリーミング応答の1回の読み取りがバイトを待つ最大秒数（超過で接続を dead と判定）。読み取りごと、全体ではない。',
    'settings.subagentMaxActive.help' => '1セッションが同時に持つ委任実行数（全レベル、メンバー、バックグラウンドエージェント含む）。超えると `Task` 呼び出しが拒否される。未設定（デフォルト）または 0 は上限なし。',
    'settings.subagentMaxConcurrent.help' => '1バッチの `Task` 呼び出しで同時に実行する数（残りは空きスロット待ち）。全エージェントプールの幅でもある。未設定（デフォルト）または 0 は上限なし。',
    'settings.subagentMaxDepth.help' => 'セッションの下に委任実行が置けるレベル数。最終レベルの実行は `Task` を持たない。1 はサブエージェントがさらに委任できない。',
    'settings.subagentMaxTurns.help' => 'プリセットに `maxTurns` が宣言されていないサブエージェント — `Task` 委任、ワークフローステージ、`executeAgents` 実行 — のステップ上限。',
    'settings.subagentModel.help' => 'プリセットが `inherit` を指定している場合、委任されたサブエージェントが実行に使うモデル。未設定ならセッションのモデルに従う。',
    'settings.summaryModel.help' => '圧縮要約を生成するモデル。未設定なら会話自身のモデルを使い、プロンプトキャッシュを再利用する。',
    'settings.symbolMap.enabled.help' => 'ランキング付きシンボルレベルのリポジトリマップをシステムプロンプトに挿入。セッションごとに一度だけ取得。',
    'settings.temperature.help' => '`custom` プロバイダがリクエストに温度指定がない場合に送るサンプリング温度。',
    'settings.terminalBackground.help' => 'アダプティブテーマがテキストの背景に想定する色: auto はターミナルに照会 (OSC 11、次に COLORFGBG); light / dark は明示的に指定。',
    'settings.testCommand.help' => 'プロジェクトルートでテストを実行するシェルコマンド (`composer test`, `pytest -q`); `autoTest` が実行するもの。',
    'settings.theme.help' => 'カラーテーマ; /theme とパレットでライブ変更。カスタムテーマは ~/.candy-code/themes 配下の JSON ファイルから読み込み。',
    'settings.thinkingBudget.help' => '思考トークン予算: `vertex` プロバイダでは Gemini `thinkingConfig`; `anthropic` プロバイダでは拡張思考 (Messages API 下限 1024、0 または未設定で両者ともオフ)。思考トークンは出力として課金。',
    'settings.titleModel.help' => 'セッション命名とプロンプト候補生成に使うモデル。未設定ならプロバイダタイプの安価な補助デフォルトをブロックモデルより先に使用。',
    'settings.transcriptJsonl.help' => '確定したトランスクリプトを `~/.candy-code/transcripts/<project>/` 配下の追記専用 JSONL ジャーナル (ファイル権限 0600) にミラーし、フックスクリプトに `transcript_path` stdin キーで参照させる。ジャーナルは生会話を保持し無制限に成長; 起動時に読み込むため変更は次回起動から反映。',
    'settings.toolInstructionCapBytes.help' => 'Edit、Write、ApplyPatch の結果が保持できる CLAUDE.md/AGENTS.md 本文の最大バイト数。超過分はマーカー付きで切り捨て。',
    'settings.toolOutputCapBytes.help' => 'Bash、Grep、Glob、Lsp、WebFetch の結果がモデルに渡せる最大バイト数。切り捨て分は結果が示すファイルに保存。',
    'settings.toolOutputPreviewLines.help' => 'トランスクリプトに表示される折りたたみツール結果の行数; Ctrl+O で残りを展開。',
    'settings.toolSpillCaptureBytes.help' => 'Bash コマンド出力 (ストリーム別) のうちメモリに保持し、結果切り捨て時にスプールファイルへ保存する最大量。出力上限を下回ることはない。',
    'settings.toolSpillMinCapBytes.help' => '切り捨てたツール結果をファイルに保存する最小結果上限。これ未満では切り捨てを通知し残りを破棄。',
    'settings.toolSpillWindowPercent.help' => '1 つのツール結果がコンテキストウィンドウを占有できる最大割合。超過時は結果をファイルに保存し、モデルには先頭と末尾のみ表示。',
    'settings.trustedProjectCommands.help' => 'スラッシュコマンドで !`cmd` シェルブロックの実行を許可するプロジェクトルート。',
    'settings.trustedProjectHooks.help' => '.candy-code/hooks.yaml の実行を許可するプロジェクトルート。',
    'settings.trustedProjectMcp.help' => '.mcp.json サーバーの起動を許可するプロジェクトルート。',
    'settings.trustedProjectSettings.help' => '.candy-code/settings*.json でプロジェクトティアキーの設定を許可するプロジェクトルート。',
    'settings.turnIdleTimeoutSeconds.help' => '実行中のターンがハングと判定されるまでの無進捗秒数; アイドル時間のみ、合計ではない。',
    'settings.ui.imageRenderMode.help' => '生成画像のターミナル描画方法; `auto` はターミナルが報告する最適プロトコルを選択。',
    'settings.ui.mediaDisplayOverrides.help' => 'レンダリングモード別の表示調整 (サイズ上限、フォールバック); キーはモード名、値は表示パラメータ。',
    'settings.vimMode.help' => '下書きボックスでの NORMAL/INSERT 編集 (i a I A o O Esc, h j k l w b e 0 $ x, dd D cc C yy y p P v V, テキストオブジェクト di" da( ciw, 回数指定 3dd d2w): NORMAL で移動・変更・削除・ヤンク、INSERT で逐語入力。バインディングではなくモード — /keys には表示されない。保存後の次のキーストロークから適用。',
    'settings.voice.apiKey.help' => '転写エンドポイントに送る Bearer キー (要求がある場合); リテラルより `${VAR}` プレースホルダ形式を推奨。',
    'settings.voice.baseUrl.help' => 'OpenAI 互換転写エンドポイントの HTTP ベース URL (末尾 `/v1` は保持); 録音データはここ以外に送信されない。デフォルトなし: ユーザーティアで設定するまで音声入力は OFF。',
    'settings.voice.language.help' => '転写言語を強制する BCP-47 コード (`en`, `de`); 未設定ならエンドポイントが自動検出。',
    'settings.voice.maxSeconds.help' => '1 回の録音のハード秒数上限 (5-600、デフォルト 120)。上限はレコーダ引数に渡すため、孤立した録音は自己停止する。',
    'settings.voice.model.help' => '転写リクエストに毎回送るモデル ID; OpenAI 互換エンドポイントでは `whisper-1` が応答。',
    'settings.watchFiles.help' => '保存ファイルに AI! (変更依頼) または AI? (質問) で終わるコメントがある場合プロンプトを送信; 通常の AI コメントはコンテキストとして付随。チャットアイドル時にポーリング; 起動後に保存されたコメントのみ、各 1 回発火。ターミナルセッション限定: ウォッチャはターミナルプロセス内で動作するため、`candy-code serve` ホストのセッションはファイル監視しない。',
    'settings.webFetchMaxBytes.help' => '取得ボディのうちメモリに保持する最大量; メモリ上限であり、モデルに届くのは出力上限。',
    'settings.webFetchTimeoutSeconds.help' => 'WebFetch のソケット読み取りが失敗するまでの最大ストール秒数。',
    'settings.webSearchBackend.help' => 'WebSearch が照会する検索サービス: `searxng` (デフォルト) は全クエリを `webSearchEndpoint` に送信; `brave`、`tavily`、`exa` は各サービスの固定ホストに接続し、API キーを環境変数 (`BRAVE_SEARCH_API_KEY`、`TAVILY_API_KEY`、`EXA_API_KEY`) で指定する必要があり、他 URL への振り替えは不可。',
    'settings.webSearchEndpoint.help' => '信頼する SearXNG インスタンスの検索 URL (`https://searx.example.org/search`); 全 WebSearch クエリがここに送信される。',
    'settings.webSearchMaxResults.help' => 'WebSearch 結果一覧の件数; 各項目はタイトル、URL、スニペット。',
    'settings.webSearchTimeoutSeconds.help' => '1 回の検索リクエストの最大許容秒数。',
    'settings.webhooks.help' => 'フック名から {secret, prompt, permissionMode?, rate?} へのマップ; POST /api/hooks/{name} がボディを (信頼不可としてエスケープ) プロンプトに挿入しバックグラウンドセッションを開始。空 (デフォルト) は何もマウントしない。rate はアドレス別・フック全体の毎分配信数。bypass-permissions は起動時にフックで拒否; モード未指定フックはサーバーモードとデフォルトの厳しい方を実行。行に signature: {scheme: "github-sha256"|"hmac-sha256", header?, deliveryHeader?} を指定可: ルートは生ボディの HMAC-SHA256 (sha256=<hex>) を行の secret で署名ヘッダ経由で検証 (GitHub はカスタムヘッダを送れないため); 署名失敗はフック別ロックアウトに合算、既知の配信 ID (GitHub スキームでは X-GitHub-Delivery、汎用では deliveryHeader) は {"ok": true, "duplicate": true} を返し第 2 セッションを開始しない。',
    'settings.webhooksOut.help' => 'エンドポイント名から {url, secret, events} へのマップ; events は turn.completed、session.ended、permission.asked、schedule.fired から選ぶ非空リスト。空 (デフォルト) はアウトバウンドを一切開かない。USER ティアのみから読み込み — プロジェクトやバンドル設定でアウトバウンドエンドポイントを追加不可。url は https 必須、http はリテラルホストが localhost またはループバックアドレスの場合のみ、userinfo は不可; secret は 16 文字以上で各配信を X-Candy-Code-Signature (正確なボディに対する sha256=<hex>) と X-Candy-Code-Timestamp で HMAC-SHA256 署名。配信はイベントループ上で非同期 — ディスパッチは応答を待たない: 接続 2 秒・POST 毎ネットワーク 10 秒の上限 (Webhook 上限であり LLM リクエストタイムアウトではない)、失敗トランスポートと 5xx は 2/8/30 秒リトライ、4xx とリダイレクトは初回で確定 (リダイレクトは追わず拒否)、128 件のインフライト上限キューは溢れ時に新ディスパッチを破棄しメモリは増やさない。起動時に読み込み; 変更は再起動で反映。',
    'settings.webhooksOut.refuse' => 'ユーザー設定の webhooksOut が使用不可: {reason}。不完全な検証のエンドポイントへの配信は拒否して起動しない — マップを修正するか、キーを削除してアウトバウンド Webhook なしで実行。',
